    for s in doc['jobs'][job]['steps']:
        if isinstance(s, dict) and isinstance(s.get('run'), str) and ('clone --reference' in s['run'] or 'xcbeautify' in s['run'] or 'Install fastlane' in (s.get('name') or '')):
            r = subprocess.run(['bash','-n'], input=s['run'], text=True, capture_output=True)
            if r.returncode != 0:
                ok = False
                print(job, s.get('name'), 'SYNTAX ERROR:', r.stderr)
            else:
                print('OK', job, '-', s.get('name'))
sys.exit(0 if ok else 1)
EOF"}

